function expenseSpecialtyName(value){return value===GENERAL_EXPENSE?'مصروف عام':(spec(value)?.name||value||'—');}
function expenseMatches(item,{from,to,branch,specialty,method}={}){return(!from||item.date>=from)&&(!to||item.date<=to)&&(!branch||item.branch===branch)&&(!specialty||item.specialty===specialty)&&(!method||item.method===method);}
function allMethodNames(rows=[]){return[...new Set([...methodRecords.map(item=>item.name),...rows.map(item=>item.method)].map(String).map(value=>value.trim()).filter(Boolean))];}
function groupRows(rows,keyFn){const map=new Map();rows.forEach(row=>{const key=String(keyFn(row)||'—');map.set(key,(map.get(key)||0)+Number(row.amount||0));});return[...map.entries()].sort((a,b)=>b[1]-a[1]);}
const monthNamesV11=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const pad2=value=>String(value).padStart(2,'0');
function monthBounds(year,month){const last=new Date(Number(year),Number(month),0).getDate();return{from:`${year}-${pad2(month)}-01`,to:`${year}-${pad2(month)}-${pad2(last)}`};}
function yearBounds(year){return{from:`${year}-01-01`,to:`${year}-12-31`};}
function tenYearBounds(){const current=Number(today().slice(0,4));return{from:`${current-9}-01-01`,to:`${current}-12-31`,startYear:current-9,endYear:current};}
function yearOptions(){const current=Number(today().slice(0,4)),years=new Set(Array.from({length:10},(_,index)=>current-index));allPayments().forEach(item=>years.add(Number(String(item.date||'').slice(0,4))));expenses.forEach(item=>years.add(Number(String(item.date||'').slice(0,4))));return[...years].filter(year=>Number.isInteger(year)&&year>1900&&year<2200).sort((a,b)=>b-a);}
function bucketKeys(mode,year,month){if(mode==='daily'){const days=new Date(Number(year),Number(month),0).getDate();return Array.from({length:days},(_,index)=>({label:String(index+1),match:date=>date===`${year}-${pad2(month)}-${pad2(index+1)}`}));}if(mode==='monthly')return monthNamesV11.map((label,index)=>({label,match:date=>Number(String(date||'').slice(5,7))===index+1}));const bounds=tenYearBounds();return Array.from({length:10},(_,index)=>bounds.startYear+index).map(y=>({label:String(y),match:date=>Number(String(date||'').slice(0,4))===y}));}
function seriesFor(rows,mode,year,month){return bucketKeys(mode,year,month).map(bucket=>({label:bucket.label,value:rows.filter(row=>bucket.match(row.date)).reduce((sum,row)=>sum+Number(row.amount||0),0)}));}
