function securitySettingsHtml(){const user=currentUser(),admin=!securityState.users.length||user?.role==='admin';return`<div class="card settings-card-prod security-settings-v11"><h2>الأمان والمستخدمون</h2><p>${securityState.users.length?'كل تشغيل جديد يتطلب اسم المستخدم وPIN.':'لا يوجد حساب حاليًا، لذلك التطبيق يفتح بدون شاشة دخول. أول حساب يجب أن يكون Admin.'}</p>${admin?`<div class="users-list-v11">${securityState.users.map(item=>`<div class="method-row-v11"><div><b>${esc(item.username)}</b><small>${item.role==='admin'?'Admin':'مستخدم'}</small></div><button class="mini edit-user-v11" data-id="${esc(item.id)}">تعديل / تغيير PIN</button></div>`).join('')}</div><button class="button" id="addUserV11">${securityState.users.length?'＋ إضافة مستخدم':'إنشاء Admin الأول'}</button>`:'<div class="info-box">إدارة المستخدمين والصلاحيات متاحة للـ Admin فقط.</div>'}</div>`;}
